create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,display_name text not null default '',bio text not null default '',phone_visible boolean not null default false,message_privacy text not null default 'followers' check(message_privacy in('everyone','followers','nobody')),created_at timestamptz not null default now());
create table if not exists public.private_contacts(user_id uuid primary key references public.profiles(id) on delete cascade,phone text unique not null);
create table if not exists public.follows(follower_id uuid references public.profiles(id) on delete cascade,followed_id uuid references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(follower_id,followed_id),check(follower_id<>followed_id));
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body)<=3000),created_at timestamptz not null default now());
create table if not exists public.post_likes(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(post_id,user_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,parent_id uuid references public.comments(id) on delete cascade,body text not null check(length(body)<=1500),created_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id) on delete cascade,recipient_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body)<=5000),created_at timestamptz not null default now(),read_at timestamptz,check(sender_id<>recipient_id));
alter table public.profiles enable row level security;
alter table public.private_contacts enable row level security;
alter table public.follows enable row level security;
alter table public.posts enable row level security;
alter table public.post_likes enable row level security;
alter table public.comments enable row level security;
alter table public.messages enable row level security;
create policy "profile read" on public.profiles for select to authenticated using(true);
create policy "profile insert own" on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy "profile update own" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "private contact owner only" on public.private_contacts for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "follows read" on public.follows for select to authenticated using(true);
create policy "follow self" on public.follows for insert to authenticated with check(auth.uid()=follower_id);
create policy "unfollow self" on public.follows for delete to authenticated using(auth.uid()=follower_id);
create policy "posts read" on public.posts for select to authenticated using(true);
create policy "post own insert" on public.posts for insert to authenticated with check(auth.uid()=user_id);
create policy "post own update" on public.posts for update to authenticated using(auth.uid()=user_id);
create policy "post own delete" on public.posts for delete to authenticated using(auth.uid()=user_id);
create policy "likes read" on public.post_likes for select to authenticated using(true);
create policy "like self" on public.post_likes for insert to authenticated with check(auth.uid()=user_id);
create policy "unlike self" on public.post_likes for delete to authenticated using(auth.uid()=user_id);
create policy "comments read" on public.comments for select to authenticated using(true);
create policy "comment self" on public.comments for insert to authenticated with check(auth.uid()=user_id);
create policy "comment update own" on public.comments for update to authenticated using(auth.uid()=user_id);
create policy "comment delete own" on public.comments for delete to authenticated using(auth.uid()=user_id);
create policy "message participants read" on public.messages for select to authenticated using(auth.uid()=sender_id or auth.uid()=recipient_id);
create policy "send if recipient allows" on public.messages for insert to authenticated with check(auth.uid()=sender_id and exists(select 1 from public.profiles p where p.id=recipient_id and (p.message_privacy='everyone' or (p.message_privacy='followers' and exists(select 1 from public.follows f where f.follower_id=recipient_id and f.followed_id=auth.uid())))));
create policy "recipient mark read" on public.messages for update to authenticated using(auth.uid()=recipient_id) with check(auth.uid()=recipient_id);
create or replace function public.find_user_by_phone(phone_to_find text) returns table(id uuid,username text,display_name text,bio text) language sql security definer set search_path=public as $$ select p.id,p.username,p.display_name,p.bio from public.private_contacts c join public.profiles p on p.id=c.user_id where c.phone=phone_to_find and p.phone_visible=true and p.id<>auth.uid() limit 1 $$;
revoke all on function public.find_user_by_phone(text) from public;
grant execute on function public.find_user_by_phone(text) to authenticated;
